    private const string Superblock128FrameDigest =
        "280b05b2298da9b95457087ddfcec231bbfcb598751b6a4aaf31549a9deaef22";

    [Theory]
    [InlineData(RepeatedIvfBase64, RepeatedFrameDigest)]
    [InlineData(OddVectorIvfBase64, OddVectorFrameDigest)]
    [InlineData(Superblock128IvfBase64, Superblock128FrameDigest)]
    public void DecodeDisplayFrames_IntraBlockCopyClip_MatchesDav1dExactly(string clipBase64, string expectedDigest)
    {
        using MemoryStream stream = new(Convert.FromBase64String(clipBase64));
        List<Av1DisplayFrame> frames = Av1DecoderCore.DecodeDisplayFrames(stream);

        Assert.Single(frames);
        using IncrementalHash hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        hash.AppendData(Av1TestData.CroppedBytes(frames[0].Luma));
        hash.AppendData(Av1TestData.CroppedBytes(frames[0].ChromaU));
        hash.AppendData(Av1TestData.CroppedBytes(frames[0].ChromaV));
        Assert.Equal(expectedDigest, Convert.ToHexString(hash.GetHashAndReset()).ToLowerInvariant());
    }
